1	// THE PACK MANIFEST SPEC — the single declarative statement of what a
2	// `pack.mjs` may and must carry. Everything a pack declares about itself is
3	// described here once, and `validateManifest` is the only thing that judges a
4	// manifest against it. The loader calls it on every pack it imports (canon and a
5	// consumer's own `local_packs/` alike), so a malformed or incomplete manifest
6	// surfaces as a blocking `config` error at load — the same class as invalid JSON
7	// in `.claudinite-checks.json`.
8	//
9	// WHY A SPEC AND NOT A CHECK. A required manifest field is part of the pack
10	// contract, not a conformance opinion about a repo's content: a conformance rule
11	// would have to be declared BY a pack, run only when that pack is active, and
12	// re-derive the manifest by reading its source text — enforcing the shape of the
13	// system from inside one of its members. The spec is upstream of every pack, so
14	// there is nothing to declare and nothing to parse.
15	//
16	// Dependency-free by the engine's module rule: no imports, no filesystem. The
17	// caller supplies the facts from disk (the `skills/` directory listing), so this
18	// module is pure and testable standalone.
19	
20	// The routing budget. Both sides of `ruleRoutingGuidance` are emitted as one row
21	// of a table every session loads (engine/pack_loader/inject-pack-prose.mjs), so
22	// the cap is a context cost, not a style preference: enough for a boundary and a
23	// pointer to the pack that owns the other side.
24	export const MAX_ROUTING_WORDS = 20;
25	
26	// The two conformance scopes. A rule's scope is its PLACEMENT on the manifest —
27	// `worldRules` audit repo state, `workRules` judge the change and session in
28	// front of you — so the two runners' partition is declared where a reader of the
29	// pack can see it, and a rule module never restates (or contradicts) it.
30	export const RULE_SCOPES = { worldRules: 'world', workRules: 'work' };
31	
32	const isPlainObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
33	const isStringArray = (v) => Array.isArray(v) && v.every((x) => typeof x === 'string');
34	const isRuleArray = (v) => Array.isArray(v) && v.every((x) => isPlainObject(x) && typeof x.id === 'string' && typeof x.run === 'function');
35	// The executor-session vocabulary. It lives HERE, with the manifest spec, because a
36	// pack's `sessionScope` is now where the scope is declared; the scheduler's
37	// session-scope.mjs imports it rather than keeping a second copy, so a pack manifest
38	// and the resolver cannot disagree about what the legal values are. (The direction
39	// matters: scheduler imports pack_loader, never the reverse.)
40	export const SESSION_SCOPES = ['self', 'fleet'];
41	const isSessionScope = (v) => SESSION_SCOPES.includes(v);
42	
43	// Every field a manifest may carry. `required` fields must be present; the rest
44	// are validated only when declared. An UNDECLARED field is an error: the spec is
45	// the closed vocabulary of a pack, so a typo (`rule:`, `skill:`) fails loudly
46	// instead of being silently ignored forever.
47	export const PACK_FIELDS = {
48	  id: { required: true, describe: 'the pack id, matching its directory name', valid: (v) => typeof v === 'string' && v.length > 0 },
49	  ruleRoutingGuidance: { required: true, describe: 'what belongs in this pack and what does not, each at most 20 words', valid: isPlainObject },
50	  badge: { describe: 'the pack badge filename, resolved off the pack directory', valid: (v) => typeof v === 'string' },
51	  detect: { describe: 'a fingerprint predicate over the repo context, or null', valid: (v) => v === null || typeof v === 'function' },
52	  marker: { describe: 'a human-readable glob naming what detect looks for, or null', valid: (v) => v === null || typeof v === 'string' },
53	  prose: { describe: 'the RULES.md filename injected at session start, or null', valid: (v) => v === null || typeof v === 'string' },
54	  seededByDefault: { describe: 'whether bootstrap --init seeds this pack everywhere', valid: (v) => typeof v === 'boolean' },
55	  sessionScope: { describe: "the executor session every task in this pack needs ('self' default, or 'fleet' for a pack whose reach is other repos)", valid: isSessionScope },
56	  requires: { describe: 'pack ids this pack depends on, resolved when the declaration is written', valid: isStringArray },
57	  contributes: { describe: 'rules addressed to another pack, keyed by that pack id', valid: isPlainObject },
58	  contributedRules: { describe: 'the seam interpreting other packs contributions to this one', valid: (v) => typeof v === 'function' },
59	  env: { describe: 'environment requirements the pack needs to run its checks', valid: isPlainObject },
60	  questions: { describe: 'the pack adoption-interview questions', valid: (v) => Array.isArray(v) },
61	  skills: { describe: 'the skill directory names bundled under this pack skills/', valid: isStringArray },
62	  worldRules: { describe: 'rules auditing repo state (check_the_world)', valid: isRuleArray },
63	  workRules: { describe: 'rules judging the current change and session (check_the_work)', valid: isRuleArray },
64	};
65	
66	const REQUIRED = Object.entries(PACK_FIELDS).filter(([, f]) => f.required).map(([k]) => k);
67	
68	const wordCount = (s) => s.trim().split(/\s+/).filter(Boolean).length;
69	
