2	// source of truth for what a `tasks/<name>/task.mjs` default export must carry.
3	// Both the author-time `task-declaration-shape` check and the executor-side
4	// `validate-dispatch` validate against this one function, so the accepted shape
5	// can never drift between the two surfaces.
6	
7	import { FREQUENCIES } from './slots.mjs';
8	import { MODEL_FAMILIES } from './model-map.mjs';
9	
10	// A declared timeout is always a whole number of seconds, > 0.
11	const isPositiveInt = (n) => Number.isInteger(n) && n > 0;
12	
13	// A prework command must stay inside its own task directory — no absolute
14	// path and no `..` traversal in the command string — the same containment the
15	// worker-file rule gives agent_instructions (task-prework DESIGN §2).
16	const escapesTaskDir = (cmd) => /(^|\s)\//.test(cmd) || cmd.includes('..');
17	
18	// The 2026-08-06 phase-language rename (owner): task execution is two similar,
19	// consecutive phases — deterministic PREWORK, then AGENTIC WORK — and the field
20	// names say so instead of framing the code phase as preparation for the agent.
21	// Legacy names stay accepted here (consumer local packs rename on their own
22	// clock, driven by a migration note), canonical names win when both are present.
23	const LEGACY_FIELDS = { agent_preprocessing: 'prework', agent_preprocessing_timeout: 'prework_timeout' };
24	
25	// Return the declaration with canonical field names. Non-objects pass through
26	// untouched so validateTaskDeclaration still reports them. Loaders (discover,
27	// resolve-dispatch) normalize once; everything downstream sees only `prework`.
28	export function normalizeTaskDeclaration(decl) {
29	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) return decl;
30	  const out = { ...decl };
31	  for (const [legacy, canonical] of Object.entries(LEGACY_FIELDS)) {
32	    if (out[legacy] !== undefined) {
33	      if (out[canonical] === undefined) out[canonical] = out[legacy];
34	      delete out[legacy];
35	    }
36	  }
37	  return out;
38	}
