57	// of what its due tasks declare. `fleet` is canon-only (consumers cannot declare
58	// it) — that restriction is enforced where signals are collected, not here; the
59	// shape check only asserts a declared name is a real collector.
60	export const SIGNAL_NAMES = [
61	  'commits', 'prs', 'issues', 'branches', 'release',
62	  'localPacks', 'sharedMount', 'conversationLogs', 'stamp', 'fleet',
63	];
