65	// Validate one task declaration. Returns an array of `{ what, fix }` problems —
66	// empty means the declaration is well-formed. Pure: no I/O, no imports of the
67	// task itself; the caller supplies the already-loaded default export.
68	export function validateTaskDeclaration(raw) {
69	  const decl = normalizeTaskDeclaration(raw);
70	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) {
71	    return [{ what: 'task.mjs does not default-export a declaration object', fix: 'export default { id, frequency, precondition_signals, agent_model, expected_outcome, agent_instructions, precondition }' }];
72	  }
73	  const problems = [];
74	  const bad = (what, fix) => problems.push({ what, fix });
75	
76	  if (typeof decl.id !== 'string' || decl.id.trim() === '') {
77	    bad('the task has no string "id"', 'give the task an "id" matching its directory name');
78	  }
79	  if (!FREQUENCIES.includes(decl.frequency)) {
