20	
21	test('fleet-fit: weekly, and ceilinged at open-pr — a pack declaration is always reviewed', () => {
22	  assert.equal(decl.id, 'fleet-fit');            // must match its directory name (discover.mjs)
23	  // A repo's SHAPE is slow-moving; a daily sweep would re-ask a question whose answer
24	  // cannot have changed.
25	  assert.equal(decl.frequency, 'weekly');
26	  // The ceiling is the guard that matters most here: declaring a pack switches on
27	  // conformance checks that run in the member's CI from the moment they land, so a
28	  // wrong adoption must never auto-merge. verify-outcome.mjs enforces this in code.
29	  assert.equal(decl.expected_outcome, 'open-pr');
30	  assert.notEqual(decl.expected_outcome, 'merged-pr');
31	  assert.deepEqual(decl.precondition_signals, []);
32	});
33	
34	test('fleet-fit: declares no session scope — the enforcer repo\'s executor carries the reach', async () => {
35	  // The fleet access comes from how the enforcer repo is provisioned (declaring
36	  // sheepdog is the statement of reach), never from a per-task ask. The deprecated
37	  // field must not creep back in here — this task would be the tempting place.
38	  assert.equal(decl.session_scope, undefined);
39	  const { default: pack } = await import('../../../../packs/sheepdog/pack.mjs');
40	  assert.equal(pack.sessionScope, undefined);   // and no pack-level spelling either
41	});
42	
43	test('fleet-fit: two stages — a bounded, task-local sweep, then an agent', () => {
44	  assert.equal(decl.prework, 'node worker.mjs');
45	  assert.ok(!decl.prework.includes('..'));   // contract: no traversal out of the task dir
46	  assert.ok(Number.isInteger(decl.prework_timeout) && decl.prework_timeout > 0);
47	  assert.ok(existsSync(join(taskDir, 'worker.mjs')));
